  (SELECT COUNT(*) FROM aps_badilag.abt_variabel v WHERE v.no_var BETWEEN 11120 AND 11199 AND NOT EXISTS (SELECT 1 FROM (SELECT 11120 AS n, '2479fefd72fd69fdcd5ec10f596a9049' AS h UNION ALL SELECT 11121 AS n, 'b4abbec87269eadec502028eb86aaab4' AS h UNION ALL SELECT 11122 AS n, '276cc96fcdc02b22dc731c5b530ff04e' AS h UNION ALL SELECT 11123 AS n, 'e82fb52315deb2700a124496c8aae670' AS h UNION ALL SELECT 11124 AS n, 'b159c520aede69c176ee3d896b7ebd45' AS h UNION ALL SELECT 11130 AS n, 'a9acf87f780fb5f95410fd52667ab65b' AS h UNION ALL SELECT 11131 AS n, '746f39d3827a0f271650ec74fbec3c58' AS h UNION ALL SELECT 11132 AS n, '2c5e3702dd041c153e5601b6ac24f013' AS h UNION ALL SELECT 11133 AS n, '706968462fca879a88f454e98ee4a9d0' AS h UNION ALL SELECT 11134 AS n, '3c2e2bca110e5fbcc4e7397ad2ec2365' AS h UNION ALL SELECT 11135 AS n, '4558a81aa20ece9f0e73a584c67eb51c' AS h UNION ALL SELECT 11136 AS n, '3f1c4c712f3d2509ac5284f9a63b0fd5' AS h UNION ALL SELECT 11137 AS n, '00340ad01fde186faff213e5e66a0852' AS h UNION ALL SELECT 11138 AS n, 'ea540e058b21186f939c5b1858e5b2a8' AS h UNION ALL SELECT 11139 AS n, '39bac46d2cb8f9f3fbcb092772fa0dbf' AS h UNION ALL SELECT 11140 AS n, '075fc7a83f36224d33807d2458066e47' AS h UNION ALL SELECT 11141 AS n, '07ac69d651785ab3435328526e24ba17' AS h UNION ALL SELECT 11142 AS n, '9af5af9bb3a4c82b18db6cf18b2c55ae' AS h UNION ALL SELECT 11143 AS n, 'e024eaf2e129f2c053ac9045c09870a7' AS h UNION ALL SELECT 11144 AS n, '6526cb6f4134def16eb9e6e93ec462a9' AS h UNION ALL SELECT 11145 AS n, 'ec4f03dda16caa8ed040e1a2952142c3' AS h UNION ALL SELECT 11150 AS n, '51393fb350f061a4641d1fcbcefafbfd' AS h UNION ALL SELECT 11151 AS n, '52e692b7b4e1c3a129f2cb4d0604ee89' AS h UNION ALL SELECT 11152 AS n, '266e5f67e1e00442fc78cb715fba4769' AS h UNION ALL SELECT 11153 AS n, '7938dcc2ab6cb961bcb0c09a005e0721' AS h UNION ALL SELECT 11154 AS n, '6831391be2c417b95e433fac5610db76' AS h UNION ALL SELECT 11155 AS n, 'a9575c616c90309cf3b4a9cb2272c6b8' AS h UNION ALL SELECT 11156 AS 